// The telegram fields come from the Normalize node; the roster rows are the node input.
const norm = $('Normalize Teacher Report').first().json;
const roster = $input.all().map(i => i.json);
const rawText = String(norm.report_text || '');
const m = rawText.match(/child\s*[:=]\s*([^\n;,/]+)/i) || rawText.match(/name\s*[:=]\s*([^\n;,/]+)/i);
let childName = (m ? m[1] : '').trim();
function normName(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').trim(); }
let matched = null;
if (childName) {
  const want = normName(childName);
  for (const r of roster) {
    const rn = normName(r.child_name);
    if (rn === want || (rn && (rn.includes(want) || want.includes(rn)))) { matched = r; break; }
  }
}
return [{ json: { ...norm, child_name: childName, matched: matched, found: !!matched } }];

const item = $input.first().json;
const raw = String(item.output || '');
let parsed = {};
try { parsed = JSON.parse(raw.replace(/```json/gi, '').replace(/```/g, '').trim()); }
catch (e) { const m = raw.match(/\{[\s\S]*\}/); if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} } }
const ok = !!(parsed && parsed.child_name && parsed.summary);
const concern = !!(parsed && (parsed.concern === true || parsed.concern === 'true'));
const followUp = !!(parsed && (parsed.follow_up === true || parsed.follow_up === 'true'));
return [{ json: { ...item, ai: parsed, parse_ok: ok, child_name_ai: parsed.child_name || '', ai_summary: parsed.summary || '', concern: concern, concern_type: parsed.concern_type || '', follow_up: followUp } }];

