const today = new Date(Date.now() + 7 * 3600 * 1000).toISOString().slice(0, 10);
const roster = $('Read Roster for Sweep').all().map(i => i.json);
const reports = $input.all().map(i => i.json);
const reported = new Set(reports.map(r => String(r.child_name || '').trim().toLowerCase()));
const missing = roster.filter(c => !reported.has(String(c.child_name || '').trim().toLowerCase()));
return [{ json: { today: today, total_children: roster.length, reported_count: reports.length, missing_count: missing.length, missing_list: missing.map(m => m.child_name), has_missing: missing.length > 0 } }];

const roster = $('Read Roster for Digest').all().map(i => i.json);
const reports = $input.all().map(i => i.json);
const byClass = {};
const concerns = [];
for (const r of reports) {
  const cls = String(r.class_name || 'Unassigned');
  byClass[cls] = (byClass[cls] || 0) + 1;
  if (r.concern === true || r.concern === 'true' || String(r.concern).toLowerCase() === 'true') {
    concerns.push(String(r.child_name || '?') + ' (' + String(r.concern_type || 'general') + ')');
  }
}
const total = reports.length;
return [{ json: { total_reports: total, report_count: total, concern_count: concerns.length, concerns_list: concerns, class_breakdown: byClass, roster_size: roster.length, total_children: roster.length, has_reports: total > 0 } }];

